:not(body):has(> .driver-active-element) { overflow: hidden !important; }
.driver-no-interaction, .driver-no-interaction * { pointer-events: none !important; }
.driver-popover-footer button:focus, .driver-popover-footer button:hover { background-color: rgb(247, 247, 247); }
.driver-popover-navigation-btns { display: flex; flex-grow: 1; justify-content: flex-end; }
.driver-popover-navigation-btns button + button { margin-left: 4px; }
.driver-popover-arrow { content: ""; position: absolute; border: 5px solid rgb(255, 255, 255); }
.driver-popover-arrow-side-over { display: none; }
.driver-popover-arrow-side-left { left: 100%; border-right-color: rgba(0, 0, 0, 0); border-bottom-color: rgba(0, 0, 0, 0); border-top-color: rgba(0, 0, 0, 0); }
.driver-popover-arrow-side-right { right: 100%; border-left-color: rgba(0, 0, 0, 0); border-bottom-color: rgba(0, 0, 0, 0); border-top-color: rgba(0, 0, 0, 0); }
.driver-popover-arrow-side-top { top: 100%; border-right-color: rgba(0, 0, 0, 0); border-bottom-color: rgba(0, 0, 0, 0); border-left-color: rgba(0, 0, 0, 0); }
.driver-popover-arrow-side-bottom { bottom: 100%; border-left-color: rgba(0, 0, 0, 0); border-top-color: rgba(0, 0, 0, 0); border-right-color: rgba(0, 0, 0, 0); }
.driver-popover-arrow-side-center { display: none; }
