/* Loading overlay */
body.is-loading { overflow: hidden; }
body.is-loading #__next { opacity: 0; visibility: hidden; height: 0; overflow: hidden; }
.page-loader { position: fixed; inset: 0px; display: flex; align-items: center; justify-content: center; background: rgba(255, 255, 255, 0.92); z-index: 2000; transition: opacity 200ms ease, visibility 200ms ease; }
body:not(.is-loading) .page-loader { opacity: 0; visibility: hidden; pointer-events: none; }
.page-loader__card { display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 24px 28px; border-radius: 16px; background: rgb(255, 255, 255); box-shadow: rgba(0, 0, 0, 0.08) 0px 8px 24px; min-width: 220px; color: rgb(31, 41, 55); text-align: center; }
.page-loader__spinner { width: 40px; height: 40px; border-radius: 50%; border: 3px solid rgba(0, 0, 0, 0.08); border-top-color: var(--color-primary-pure, rgb(184, 31, 37)); animation: page-loader-spin 0.9s linear infinite; }
.page-loader__title { font-weight: 700; font-size: 1rem; }
.page-loader__subtitle { font-size: 0.875rem; color: rgba(0, 0, 0, 0.6); }
@keyframes page-loader-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
   .page-loader__spinner { animation: none; border-top-color: rgba(0, 0, 0, 0.08); }
}

/* Modal PIX */
.pix-modal-overlay { position: fixed; inset: 0px; background: rgba(0, 0, 0, 0.5); display: flex; align-items: center; justify-content: center; z-index: 1999; opacity: 0; visibility: hidden; transition: all 200ms ease; }
