.pix-modal { background: rgb(255, 255, 255); border-radius: 20px; padding: 32px; max-width: 559px; width: 90%; box-shadow: rgba(0, 0, 0, 0.15) 0px 15px 50px; transform: scale(0.9); transition: transform 200ms ease; }
