function updateExtratoDebitos() {
  if (!dados || !dados.extratoDebitos) return;
  
  console.log('Atualizando extrato débitos com ' + dados.extratoDebitos.length + ' anos');
  
  var container = document.querySelector('#detalhamento-valores .css-dei9yf');
  if (!container) {
    console.error('Container não encontrado');
    return;
  }
  
  // Limpar container e criar acordeões para TODOS os anos
  container.innerHTML = '';
  
  dados.extratoDebitos.forEach(function(extrato, idx) {
    var ano = extrato.anoExercicio;
    var isFirst = idx === 0;
    
    // Calcular total de débitos NÃO PAGOS do ano
    var totalNaoPagoAno = 0;
    if (extrato.parcelas) {
      extrato.parcelas.forEach(function(parcela) {
        if (!parcela.estaPago) {

         if (parcela.descricao != 'COTA ÚNICA') {
            totalNaoPagoAno += parcela.valorTotal;
         }
        }
      });
    }
    
    // Template do accordion
    var html = '<div class="detalhamento-accordion-' + ano + ' css-19sp7wp" data-testid="detalhamento-accordion-' + ano + '">';
    html += '<div class="MuiPaper-root MuiPaper-elevation MuiPaper-rounded MuiPaper-elevation1 MuiAccordion-root MuiAccordion-rounded ' + (isFirst ? 'Mui-expanded' : '') + ' MuiAccordion-gutters css-8faoo5">';
    html += '<div class="MuiButtonBase-root MuiAccordionSummary-root ' + (isFirst ? 'Mui-expanded' : '') + ' MuiAccordionSummary-gutters css-11ml8c9" tabindex="0" role="button" aria-expanded="' + isFirst + '" data-testid="detalhamento-accordion-summary-' + ano + '">';
    html += '<div class="MuiAccordionSummary-content ' + (isFirst ? 'Mui-expanded' : '') + ' MuiAccordionSummary-contentGutters css-l0jafl">';
    html += '<div class="summary-ano"><div class="MuiFormGroup-root hidden-checkbox css-1h7anqn">';
    html += '<label class="MuiFormControlLabel-root MuiFormControlLabel-labelPlacementEnd css-1jaw3da" data-testid="detalhamento-accordion-select-period-' + ano + '">';
    html += '<span class="MuiButtonBase-root MuiCheckbox-root MuiCheckbox-colorPrimary MuiCheckbox-sizeMedium PrivateSwitchBase-root MuiCheckbox-root MuiCheckbox-colorPrimary MuiCheckbox-sizeMedium ' + (isFirst ? 'Mui-checked' : '') + ' MuiCheckbox-root MuiCheckbox-colorPrimary MuiCheckbox-sizeMedium css-gsw46m">';
