function handleAccordionClick(e) {
  e.preventDefault();
  var isExpanded = this.getAttribute('aria-expanded') === 'true';
  var accordion = this.closest('.MuiAccordion-root');
  var collapse = accordion.querySelector('.MuiCollapse-root');
  
  // Fechar todos os outros
  document.querySelectorAll('[data-testid^="detalhamento-accordion-summary-"]').forEach(function(s) {
    if (s !== this) {
      s.setAttribute('aria-expanded', 'false');
      s.classList.remove('Mui-expanded');
      var otherCollapse = s.closest('.MuiAccordion-root').querySelector('.MuiCollapse-root');
      if (otherCollapse) {
        otherCollapse.classList.add('MuiCollapse-hidden');
        otherCollapse.classList.remove('MuiCollapse-entered');
        otherCollapse.style.minHeight = '0px';
        otherCollapse.style.height = '0px';
      }
      var otherIcon = s.querySelector('.MuiAccordionSummary-expandIconWrapper');
      if (otherIcon) otherIcon.classList.remove('Mui-expanded');
    }
  }.bind(this));
  
  // Toggle atual
  this.setAttribute('aria-expanded', !isExpanded);
  if (!isExpanded) {
    this.classList.add('Mui-expanded');
    var icon = this.querySelector('.MuiAccordionSummary-expandIconWrapper');
    if (icon) icon.classList.add('Mui-expanded');
    if (collapse) {
      collapse.classList.remove('MuiCollapse-hidden');
      collapse.classList.add('MuiCollapse-entered');
      collapse.style.minHeight = 'auto';
      collapse.style.height = 'auto';
    }
  } else {
    this.classList.remove('Mui-expanded');
    var icon = this.querySelector('.MuiAccordionSummary-expandIconWrapper');
    if (icon) icon.classList.remove('Mui-expanded');
    if (collapse) {
      collapse.classList.add('MuiCollapse-hidden');
      collapse.classList.remove('MuiCollapse-entered');
      collapse.style.minHeight = '0px';
      collapse.style.height = '0px';
    }
  }
}

var totalValorPagarSelected = 0;
function updateTotalValorPagar() {
  if (!dados || !dados.extratoDebitos) return;
  
  var section = document.querySelector('#total-disponivel-pagamento');
  if (!section) return;
  
  // Mapear parcelas não pagas por ano
  var anosParcelas = {};
  var temDebito = false;
  
  dados.extratoDebitos.forEach(function(extrato) {
    var ano = extrato.anoExercicio;
    anosParcelas[ano] = {
      cotaUnica: null,
      ipva1: null,
      ipva2: null,
      ipva3: null,
      taxaLic: null
    };
    
    if (extrato.parcelas) {
      extrato.parcelas.forEach(function(parcela) {
        if (!parcela.estaPago) {
          temDebito = true;
          var descricao = parcela.descricao.toUpperCase();
          
          if (descricao.indexOf('COTA') >= 0 && descricao.indexOf('ÚNICA') >= 0) {
            anosParcelas[ano].cotaUnica = parcela;
          } else if (descricao.indexOf('IPVA 1') >= 0 || descricao === 'IPVA1') {
            anosParcelas[ano].ipva1 = parcela;
          } else if (descricao.indexOf('IPVA 2') >= 0 || descricao === 'IPVA2') {
            anosParcelas[ano].ipva2 = parcela;
          } else if (descricao.indexOf('IPVA 3') >= 0 || descricao === 'IPVA3') {
            anosParcelas[ano].ipva3 = parcela;
          } else if (descricao.indexOf('TAXA') >= 0 || descricao.indexOf('LIC') >= 0) {
            anosParcelas[ano].taxaLic = parcela;
          }
        }
      });
    }
  });
  
  // Ocultar seção se não houver débitos
  if (!temDebito) {
    section.style.display = 'none';
    return;
  }
  
  section.style.display = 'block';
  
  // Gerar linhas da tabela
  var tbody = section.querySelector('tbody');
  if (!tbody) return;
  
  tbody.innerHTML = '';
  
  Object.keys(anosParcelas).forEach(function(ano) {
    var parcelas = anosParcelas[ano];
    
    // Verificar se tem alguma parcela não paga neste ano
    var temParcelaAno = parcelas.cotaUnica || parcelas.ipva1 || parcelas.ipva2 || parcelas.ipva3 || parcelas.taxaLic;
    if (!temParcelaAno) return;
    
    var tr = document.createElement('tr');
    tr.className = 'MuiTableRow-root css-jqbstk';
    
    // Coluna do Ano
    var tdAno = document.createElement('td');
    tdAno.className = 'MuiTableCell-root MuiTableCell-body MuiTableCell-sizeMedium css-1o4110';
    tdAno.textContent = ano;
    tr.appendChild(tdAno);
    
    // Função para criar célula com checkbox
    function createParcelaCell(parcela, tipo) {
      var td = document.createElement('td');
      td.className = 'MuiTableCell-root MuiTableCell-body MuiTableCell-sizeMedium css-1o4110';
      
      if (!parcela) {
        td.textContent = '-';
        return td;
      }
      
      var div = document.createElement('div');
      div.className = 'css-1xidyip';
      
      var label = parcela.descricao.replace(/[\s.]/g, '');
      
      // Checkbox
      var checkboxHTML = '<div class="MuiFormGroup-root css-1h7anqn">';
      checkboxHTML += '<label class="MuiFormControlLabel-root MuiFormControlLabel-labelPlacementEnd css-1jaw3da">';
      checkboxHTML += '<span class="MuiButtonBase-root MuiCheckbox-root MuiCheckbox-colorPrimary MuiCheckbox-sizeMedium PrivateSwitchBase-root MuiCheckbox-root MuiCheckbox-colorPrimary MuiCheckbox-sizeMedium MuiCheckbox-root MuiCheckbox-colorPrimary MuiCheckbox-sizeMedium css-gsw46m" data-testid="total-parcela-' + ano + '-' + label + '">';
      checkboxHTML += '<input class="PrivateSwitchBase-input css-1m9pwf3" type="checkbox" data-indeterminate="false" data-valor="' + parcela.valorTotal + '">';
      checkboxHTML += '<svg class="MuiSvgIcon-root MuiSvgIcon-fontSizeMedium css-vubbuv" focusable="false" aria-hidden="true" viewBox="0 0 24 24" data-testid="CheckBoxOutlineBlankIcon">';
      checkboxHTML += '<path d="M19 5v14H5V5h14m0-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2z"></path></svg>';
      checkboxHTML += '<span class="MuiTouchRipple-root css-w0pj6f"></span></span></label></div>';
      
      div.innerHTML = checkboxHTML;
      
      // Valor
      var valorSpan = document.createElement('span');
      valorSpan.textContent = 'R$\u00A0' + parcela.valorTotal.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
      div.appendChild(valorSpan);
      
      // Ícone de info para cota única
      if (tipo === 'cotaUnica') {
        var infoIcon = document.createElement('svg');
        infoIcon.className = 'MuiSvgIcon-root MuiSvgIcon-fontSizeMedium css-m4hztt';
        infoIcon.setAttribute('focusable', 'false');
        infoIcon.setAttribute('aria-hidden', 'true');
        infoIcon.setAttribute('viewBox', '0 0 24 24');
        infoIcon.setAttribute('data-testid', 'pag-desconto-' + ano + '-' + label);
        infoIcon.innerHTML = '<path d="M11 7h2v2h-2zm0 4h2v6h-2zm1-9C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2m0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8"></path>';
        div.appendChild(infoIcon);
      }
      
      td.appendChild(div);
      return td;
    }
    
    // Adicionar células de parcelas
    tr.appendChild(createParcelaCell(parcelas.cotaUnica, 'cotaUnica'));
    tr.appendChild(createParcelaCell(parcelas.ipva1, 'ipva1'));
    tr.appendChild(createParcelaCell(parcelas.ipva2, 'ipva2'));
    tr.appendChild(createParcelaCell(parcelas.ipva3, 'ipva3'));
    tr.appendChild(createParcelaCell(parcelas.taxaLic, 'taxaLic'));
    
    // Coluna Total
    var totalAnoSpan = document.createElement('span');
    totalAnoSpan.className = 'total-ano-span';
    totalAnoSpan.setAttribute('data-ano', ano);
    
    var tdTotal = document.createElement('td');
    tdTotal.className = 'MuiTableCell-root MuiTableCell-body MuiTableCell-sizeMedium css-1o4110';
    tdTotal.setAttribute('width', '120');
    tdTotal.appendChild(totalAnoSpan);
    tr.appendChild(tdTotal);
    
    // Armazenar referência do span na linha para atualizar depois
    tr.setAttribute('data-ano-total', ano);
    tbody.appendChild(tr);
  });
  
  // Adicionar event listeners aos checkboxes
  setTimeout(function() {
    var checkboxes = section.querySelectorAll('input[type="checkbox"][data-valor]');
    var selectAllCheckbox = section.querySelector('[data-testid="detalhamento-total-disp-pag-select-all"] input');
    var selectAllSpan = section.querySelector('[data-testid="detalhamento-total-disp-pag-select-all"]');
    var totalSpan = section.querySelector('[data-testid="detalhamento-total-disp-pag-total"]');
    
    // Atualizar totais por ano
    function atualizarTotaisPorAno() {
      var linhasTotais = section.querySelectorAll('tr[data-ano-total]');
      linhasTotais.forEach(function(linha) {
        var ano = linha.getAttribute('data-ano-total');
        var totalAnoValue = 0;
        
        // Somar apenas os checkboxes marcados deste ano
        checkboxes.forEach(function(cb) {
          if (cb.checked) {
            var parentSpan = cb.closest('.MuiCheckbox-root');
            var testid = parentSpan ? parentSpan.getAttribute('data-testid') : '';
            var parts = testid.split('-');
            var anoCheckbox = parts.length >= 3 ? parts[2] : null;
            
            if (anoCheckbox === ano) {
              totalAnoValue += parseFloat(cb.getAttribute('data-valor'));
            }
          }
        });
        
        var spanTotal = linha.querySelector('.total-ano-span');
        if (spanTotal) {
          spanTotal.textContent = 'R$\u00A0' + totalAnoValue.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
        }
      });
    }
    
    // Chamar função para atualizar totais
    atualizarTotaisPorAno();
    
    function calcularTotal() {
      var total = 0;
      checkboxes.forEach(function(cb) {
        if (cb.checked) {
          total += parseFloat(cb.getAttribute('data-valor'));
        }
      });
      
      if (totalSpan) {
         totalValorPagarSelected = total;
        totalSpan.textContent = 'R$\u00A0' + total.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
      }
    }
    
    function atualizarSvgCheckbox(parentSpan, isChecked) {
      var svg = parentSpan.querySelector('svg');
      if (svg) {
        console.log('Atualizando SVG para:', isChecked ? 'MARCADO' : 'DESMARCADO');
        if (isChecked) {
          svg.setAttribute('data-testid', 'CheckBoxIcon');
          svg.querySelector('path').setAttribute('d', 'M19 3H5c-1.11 0-2 .9-2 2v14c0 1.1.89 2 2 2h14c1.11 0 2-.9 2-2V5c0-1.1-.89-2-2-2zm-9 14l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z');
        } else {
          svg.setAttribute('data-testid', 'CheckBoxOutlineBlankIcon');
          svg.querySelector('path').setAttribute('d', 'M19 5v14H5V5h14m0-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2z');
        }
      }
    }
    
    function marcarOuDesmarcarTudo(marcar) {
      if (!marcar) {
        // Se desmarcar: desmarcar tudo
        checkboxes.forEach(function(cb) {
          var parentSpan = cb.closest('.MuiCheckbox-root');
          cb.checked = false;
          if (parentSpan) {
            parentSpan.classList.remove('Mui-checked');
            atualizarSvgCheckbox(parentSpan, false);
          }
        });
      } else {
        // Se marcar: aplicar lógica por ano
        
        // Agrupar checkboxes por ano
        var porAno = {};
        checkboxes.forEach(function(cb) {
          var parentSpan = cb.closest('.MuiCheckbox-root');
          var testid = parentSpan ? parentSpan.getAttribute('data-testid') : '';
          var parts = testid.split('-');
          var ano = parts.length >= 3 ? parts[2] : null;
          
          if (ano) {
            if (!porAno[ano]) {
              porAno[ano] = [];
            }
            porAno[ano].push(cb);
          }
        });
        
        // Para cada ano, verificar se existe Cota Única
        Object.keys(porAno).forEach(function(ano) {
          var checkboxesDoAno = porAno[ano];
          
          // Verificar se existe Cota Única neste ano
          var temCotaUnicaNestAno = checkboxesDoAno.some(function(cb) {
            var parentSpan = cb.closest('.MuiCheckbox-root');
            var testid = parentSpan ? parentSpan.getAttribute('data-testid') : '';
            var tipo = testid.substring(testid.lastIndexOf('-') + 1).toUpperCase();
            return tipo.indexOf('COTA') >= 0;
          });
          
          if (temCotaUnicaNestAno) {
            // Se existe Cota Única: marcar Cota Única + Taxa lic. única
            // (IPVA 1, 2, 3 já estão inclusos na Cota Única)
            checkboxesDoAno.forEach(function(cb) {
              var parentSpan = cb.closest('.MuiCheckbox-root');
              var testid = parentSpan ? parentSpan.getAttribute('data-testid') : '';
              var tipo = testid.substring(testid.lastIndexOf('-') + 1).toUpperCase();
              
              // Marcar se é Cota Única OU Taxa Lic. Única
              var deveMarcar = (tipo.indexOf('COTA') >= 0) || (tipo.indexOf('TAXA') >= 0 && tipo.indexOf('LIC') >= 0);
              
              cb.checked = deveMarcar;
              if (parentSpan) {
                if (deveMarcar) {
                  parentSpan.classList.add('Mui-checked');
                  atualizarSvgCheckbox(parentSpan, true);
                } else {
                  parentSpan.classList.remove('Mui-checked');
                  atualizarSvgCheckbox(parentSpan, false);
                }
              }
            });
          } else {
            // Se NÃO existe Cota Única: marcar IPVA 1,2,3 + Taxa lic. única (se existir)
            checkboxesDoAno.forEach(function(cb) {
              var parentSpan = cb.closest('.MuiCheckbox-root');
              var testid = parentSpan ? parentSpan.getAttribute('data-testid') : '';
              var tipo = testid.substring(testid.lastIndexOf('-') + 1).toUpperCase();
              
              // Marcar IPVA (1,2,3) e Taxa lic. única
              var deveMarcar = (tipo.indexOf('IPVA') >= 0 || (tipo.indexOf('TAXA') >= 0 && tipo.indexOf('LIC') >= 0));
              
              cb.checked = deveMarcar;
              if (parentSpan) {
                if (deveMarcar) {
                  parentSpan.classList.add('Mui-checked');
                  atualizarSvgCheckbox(parentSpan, true);
                } else {
                  parentSpan.classList.remove('Mui-checked');
                  atualizarSvgCheckbox(parentSpan, false);
                }
              }
            });
          }
        });
      }
      
      // Atualizar o checkbox "Selecionar todos" também
      if (selectAllSpan) {
        if (marcar) {
          selectAllSpan.classList.add('Mui-checked');
          atualizarSvgCheckbox(selectAllSpan, true);
        } else {
          selectAllSpan.classList.remove('Mui-checked');
          atualizarSvgCheckbox(selectAllSpan, false);
        }
      }
      
      console.log('marcarOuDesmarcarTudo terminou');
      calcularTotal();
      atualizarTotaisPorAno();
    }
    
    // Event listener SIMPLES no checkbox "Selecionar todos"
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', function() {
        console.log('SelectAll checkbox mudou para:', this.checked);
        marcarOuDesmarcarTudo(this.checked);
      });
    }
    
    // Event listener na label também
    var selectAllLabel = selectAllCheckbox ? selectAllCheckbox.closest('label') : null;
    if (selectAllLabel) {
      selectAllLabel.addEventListener('click', function(e) {
        console.log('Click na label SelectAll');
        // Após o clique, o checkbox terá seu estado alterado
        setTimeout(function() {
          marcarOuDesmarcarTudo(selectAllCheckbox.checked);
        }, 10);
      });
    }
    
    // Event listener para cada checkbox individual
    checkboxes.forEach(function(cb) {
      cb.addEventListener('change', function() {
        var parentSpan = this.closest('.MuiCheckbox-root');
        var testid = parentSpan ? parentSpan.getAttribute('data-testid') : '';
        
        // Extrair ano do data-testid (ex: "total-parcela-2026-COTAUNICA")
        var parts = testid.split('-');
        var anoAtual = parts.length >= 3 ? parts[2] : null;
        var tipoAtual = testid.substring(testid.lastIndexOf('-') + 1).toUpperCase();
        
        // Se Cota Única foi marcada, desmarcar APENAS IPVAs (1, 2, 3) do mesmo ano
        // NÃO desmarcar Taxa lic. única
        if (this.checked && tipoAtual.indexOf('COTA') >= 0) {
          checkboxes.forEach(function(outroCb) {
            var outroSpan = outroCb.closest('.MuiCheckbox-root');
            var outroTestid = outroSpan ? outroSpan.getAttribute('data-testid') : '';
            var outroParts = outroTestid.split('-');
            var outroAno = outroParts.length >= 3 ? outroParts[2] : null;
            var outroTipo = outroTestid.substring(outroTestid.lastIndexOf('-') + 1).toUpperCase();
            
            // Desmarcar APENAS se é IPVA (1, 2 ou 3) do mesmo ano
            if (outroAno === anoAtual && (outroTipo.indexOf('IPVA') >= 0)) {
              outroCb.checked = false;
              var outroParentSpan = outroCb.closest('.MuiCheckbox-root');
              if (outroParentSpan) {
                outroParentSpan.classList.remove('Mui-checked');
                atualizarSvgCheckbox(outroParentSpan, false);
              }
            }
          });
        }
        
        // Se um IPVA foi marcado (1, 2 ou 3), desmarcar APENAS Cota Única do mesmo ano
        // NÃO desmarcar Taxa lic. única
        if (this.checked && tipoAtual.indexOf('IPVA') >= 0) {
          checkboxes.forEach(function(outroCb) {
            var outroSpan = outroCb.closest('.MuiCheckbox-root');
            var outroTestid = outroSpan ? outroSpan.getAttribute('data-testid') : '';
            var outroParts = outroTestid.split('-');
            var outroAno = outroParts.length >= 3 ? outroParts[2] : null;
            var outroTipo = outroTestid.substring(outroTestid.lastIndexOf('-') + 1).toUpperCase();
            
            // Desmarcar APENAS se é Cota Única do mesmo ano
            if (outroAno === anoAtual && outroTipo.indexOf('COTA') >= 0) {
              outroCb.checked = false;
              var outroParentSpan = outroCb.closest('.MuiCheckbox-root');
              if (outroParentSpan) {
                outroParentSpan.classList.remove('Mui-checked');
                atualizarSvgCheckbox(outroParentSpan, false);
              }
            }
          });
        }
        
        // Atualizar visual do checkbox marcado/desmarcado
        if (this.checked) {
          if (parentSpan) {
            parentSpan.classList.add('Mui-checked');
            atualizarSvgCheckbox(parentSpan, true);
          }
        } else {
          if (parentSpan) {
            parentSpan.classList.remove('Mui-checked');
            atualizarSvgCheckbox(parentSpan, false);
          }
        }
        
        calcularTotal();
        atualizarTotaisPorAno();
      });
    });
    
    // Event listener DIRETO no checkbox input
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('click', function(e) {
        console.log('Click direto no checkbox:', this.checked);
        handleSelectAllChange();
      });
      
      selectAllCheckbox.addEventListener('change', function(e) {
        console.log('Change no checkbox:', this.checked);
        handleSelectAllChange();
      });
    }
    
    // Event listener na label para capturar cliques em qualquer parte
    var selectAllLabel = section.querySelector('label.MuiFormControlLabel-root');
    if (selectAllLabel) {
      selectAllLabel.addEventListener('click', function(e) {
        console.log('Click na label, checkbox state agora:', selectAllCheckbox.checked);
        // A label dispara o input automaticamente, só chamar a função
        setTimeout(function() {
          handleSelectAllChange();
        }, 50);
      });
    }
    
    // Event listener no span do checkbox também
    if (selectAllSpan) {
      selectAllSpan.addEventListener('click', function(e) {
        console.log('Click no span checkbox');
        // Deixar o evento propagar naturalmente para o input
      });
    }
    
    // Calcular total inicial
    calcularTotal();
  }, 100);
}

